+  @keyframes drawpath{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
+  @keyframes fadein{from{opacity:0}to{opacity:1}}
+  /* 완료 도장이 한 칸씩 찍힌다(60ms 간격, 600ms 안에 끝) */
+  .snode.press svg{animation:press .24s var(--ease-pop) both;animation-delay:calc(var(--d,0) * 60ms)}
+  @keyframes press{from{transform:scale(1.12);opacity:0}to{transform:none;opacity:1}}
+  .snode .arcp{animation:arcFill .6s .2s var(--ease-enter) both}
+  .arc-anim{animation:arcFill .7s var(--ease-enter) both}
