+  .snode .tip{animation:fadein .2s .75s both}
+  .fab.show{animation:fabin .3s var(--ease-enter) both}
+  @keyframes fabin{from{transform:translateY(12px);opacity:0}to{transform:none;opacity:1}}
+  /* '새' 메달·방금 얻은 메달 위로 흰 띠가 한 번 지나간다 */
+  .sweep{animation:sweep .5s ease-in-out .45s both}
+  .my .sweep{animation-duration:.7s;animation-delay:.2s}
+  @keyframes sweep{from{transform:translateX(0)}to{transform:translateX(210px)}}
+  /* 완료 카드: 1-4 칸의 호가 차고(300ms) 도장이 찍힌다(240ms) */
+  .dc4 .d4a{animation:d4out .3s linear both}
+  @keyframes d4out{0%,99%{opacity:1}100%{opacity:0}}
