+  @keyframes flipOut{0%{transform:rotateY(0);opacity:1}99%{transform:rotateY(90deg);opacity:1}100%{transform:rotateY(90deg);opacity:0}}
+  @keyframes flipIn{from{transform:rotateY(-90deg)}to{transform:rotateY(0)}}
+  /* 레벨 표장: 숫자가 2에서 3으로 넘어가고 눈금 12개가 나타난다 */
+  .roll{animation:roll .4s var(--ease-state) .3s both}
+  @keyframes roll{from{transform:translateY(0)}to{transform:translateY(-50%)}}
+  .ticks-in{animation:fadein .4s ease .3s both}
+  .hero-art::before{animation:fadein .4s ease .3s both}
+  .mv{animation:mv .4s .3s var(--ease-enter) both}
+  @keyframes mv{from{transform:translateX(var(--from))}to{transform:translateX(0)}}
