+  svg.innerHTML=`<path class="bed" d="${bed}"/>`+groups.map(g=>`<path class="${g.k}${g.k==='d'?'':' draw'}"${g.k==='d'?'':' pathLength="1"'} d="${g.d}"/>`).join('')
+    +ends.map(e=>`<circle class="end ${e.k}" cx="${e.x}" cy="${e.y}" r="5.5"/>`).join('');
+}
+const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
+function findAnchor(id){
+  const n=(String(id).match(/\d+$/)||[''])[0];
+  const c=[document.getElementById(id),...document.querySelectorAll(`[data-sa="${n}"]`)].filter(Boolean);
+  return c.find(el=>el.getClientRects().length)||null;
+}
+function flash(t){
+  const b=t&&t.querySelector?t.querySelector('.band'):null;if(!b||reduced()) return;
+  b.classList.add('flash');setTimeout(()=>b.classList.remove('flash'),600);
+}
+function focusEl(el){ if(!el) return; if(!el.matches('a,button,summary,[tabindex]')) el.setAttribute('tabindex','-1'); el.focus({preventScroll:true}); }
+function anchorHead(t){ return t.querySelector('h3, th[scope=rowgroup]')||t; }
+function applyTo(doFocus,doFlash){
+  const t=findAnchor(S.to);if(!t) return;
+  t.scrollIntoView({block:'start'});
+  if(doFlash) flash(t);
+  if(doFocus) focusEl(anchorHead(t));
+}
+/* 떠 있는 '이어서 읽기'는 요약 패널의 '이어서 읽기' 단추가 화면에 보이는 동안 숨긴다 */
+let fio=null;
+function setupFab(){
+  if(fio){fio.disconnect();fio=null;}
+  const f=document.querySelector('.fab');if(!f) return;
+  const anchor=document.querySelector('.journal .btn-go');
+  if(!anchor||!('IntersectionObserver' in window)){f.classList.add('show');return;}
+  fio=new IntersectionObserver(es=>{const e=es[es.length-1];f.classList.toggle('show',!e.isIntersecting);});
+  fio.observe(anchor);
+}
+/* 조작 띠가 sticky일 때 그 높이만큼 스크롤·초점 이동 위치를 내린다 */
+const demo=document.querySelector('.demo');
+function setSticky(){ const st=getComputedStyle(demo).position==='sticky'; document.documentElement.style.setProperty('--sticky-h',(st?demo.offsetHeight:0)+'px'); }
+if('ResizeObserver' in window) new ResizeObserver(setSticky).observe(demo);
+setSticky();
+const live=document.getElementById('live');
+let liveT=null;
+function announce(t,delay){ clearTimeout(liveT); live.textContent=''; if(t) liveT=setTimeout(()=>{live.textContent=t;},delay||250); }
+function probe(){ if(!S.probe) return; requestAnimationFrame(()=>requestAnimationFrame(()=>{document.title='sw='+document.documentElement.scrollWidth;})); }
+function render(){
+  Q2PICK=null;
+  document.body.dataset.auth=S.auth;document.body.dataset.screen=S.screen;
+  document.title=TITLES[S.screen];
+  document.querySelectorAll('.demo button[data-screen]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.screen===S.screen)));
+  document.querySelectorAll('.demo button[data-auth]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.auth===S.auth)));
+  document.getElementById('hdr').className='hdr';
+  document.getElementById('hdr').innerHTML=header();
+  document.getElementById('app').innerHTML=SCREENS[S.screen]();
+  roadSig='';drawRoad();
+  if(ro){ro.disconnect();ro=null;}
+  const map=document.getElementById('map');
+  if(map&&'ResizeObserver' in window){ro=new ResizeObserver(()=>drawRoad());ro.observe(map);}
+  setupFab();
+  // 완료 알림: 비어 있던 상태 알림 그릇에 완료 카드를 그린 뒤 글자만 넣는다(초점 이동 없음)
+  announce(S.screen==='end'&&IN()?DONE_MSG:'');
+  const f=FOCUS;FOCUS=null;
+  if(S.to) applyTo(f==='to'||f==='h1',true); else window.scrollTo(0,0);
+  // React로 옮길 때: 보기 전환 단추는 다시 마운트되지 않게 key를 고정한다
+  if(f==='toggle') focusEl(document.querySelector('.vtoggle [aria-pressed="true"]'));
+  else if(f==='h1'&&!S.to) focusEl(document.querySelector('#app h1'));
+  probe();
+}
+function closeMenu(ret){
+  const h=document.getElementById('hdr'),b=h.querySelector('.menu-btn');
+  if(!h.classList.contains('open')) return;
+  h.classList.remove('open');if(b){b.setAttribute('aria-expanded','false');if(ret) b.focus();}
+}
+document.addEventListener('click',e=>{
+  const mb=e.target.closest('.menu-btn');
+  if(mb){const h=document.getElementById('hdr');const o=!h.classList.contains('open');h.classList.toggle('open',o);mb.setAttribute('aria-expanded',String(o));return;}
+  if(!e.target.closest('#mnav')) closeMenu(false);
+  const db=e.target.closest('.demo button[data-screen]');if(db){go(db.dataset.screen,S.auth,null,'none');return;}
+  const da=e.target.closest('.demo button[data-auth]');if(da){go(S.screen,da.dataset.auth,null,'none');return;}
+  if(e.target.closest('[data-close-notice]')){S.noticeOpen=false;const n=document.getElementById('notice');if(n) n.remove();drawRoad();
+    focusEl(document.querySelector('.vtoggle [aria-pressed="true"]'));return;}
+  const sc=e.target.closest('[data-scroll]');
+  if(sc){e.preventDefault();const t=findAnchor(sc.dataset.scroll);if(t){t.scrollIntoView({behavior:reduced()?'auto':'smooth',block:'start'});flash(t);focusEl(anchorHead(t));}return;}
+  if(e.target.closest('[data-openlog]')){e.preventDefault();const l=document.getElementById('log');if(l){l.open=true;l.scrollIntoView({behavior:reduced()?'auto':'smooth',block:'start'});focusEl(l.querySelector('summary'));}return;}
+  const qb=e.target.closest('[data-q2]');
+  if(qb){Q2PICK=+qb.dataset.q2;const box=document.getElementById('q2');box.innerHTML=q2Body();focusEl(document.getElementById('ex2'));return;}
+  const g=e.target.closest('[data-go]');
+  if(g){e.preventDefault();closeMenu(false);const fo=g.closest('.vtoggle')?'toggle':(g.dataset.to?'to':'h1');go(g.dataset.go,S.auth,g.dataset.to,fo);return;}
+  if(e.target.closest('a[href="#"]')) e.preventDefault();
+});
+document.addEventListener('keydown',e=>{
+  if(e.key==='Escape'){closeMenu(true);return;}
+});
+window.addEventListener('hashchange',()=>{readHash();if(FOCUS===null) FOCUS='h1';render();});
+window.addEventListener('resize',()=>{drawRoad();setSticky();});
+readHash();render();
+if(document.fonts&&document.fonts.ready) document.fonts.ready.then(()=>{drawRoad();if(S.to) applyTo(false,false);probe();});
+</script>
+</body>
+</html>
